export const GUIDE_SECTIONS: GuideSection[] = [
  {"id": "core-loop", "title": "The Core Loop", "content": "Deploy topside from Speranza (solo/duo/trio) onto one of the maps (Dam Battlegrounds, Buried City, Spaceport, Blue Gate, Stella Montis, plus the 5th map added in Riven Tides), loot containers and ARC wrecks, complete trader quests, avoid or fight ARC machines and other Raiders, then reach an extraction point before the raid timer ends. Back in Speranza: sell, craft, upgrade the workshop, spend skill points, repeat."},
  {"id": "extraction", "title": "Extraction Rules", "content": "Raids last roughly 30 minutes with a storm/ARC lockdown at the end; multiple extraction points (some require holding an interaction, some are hatches/elevators/rafts). Dying loses everything except Safe Pocket items. Extraction camping is considered bad etiquette but happens."},
  {"id": "loadout", "title": "Loadouts, Death and the Safe Pocket", "content": "", "subsections": [{"title": "What you bring", "content": "Custom loadout: primary + secondary weapon, shield (Light/Medium/Heavy), augment/backpack, quick-slot consumables (heals, shield rechargers, grenades, gadgets), ammo. Or a Free Loadout (starter weapon, ammo, bandages, shield recharger, utility) with no cooldown."}, {"title": "On death", "content": "Everything equipped and in the backpack is dropped and lootable by other Raiders/lost; only Safe Pocket contents are kept. Keys and quest items behaviour: not captured."}, {"title": "Safe pocket", "content": "1 Safe Pocket by default with any custom loadout (even 'naked' = 10 backpack slots + 1 safe pocket). Looting Mk.2 augment = 2 Safe Pockets; Epic looting augment = 3. Free Loadout has NO Safe Pocket."}, {"title": "Insurance", "content": "No insurance/'secure container purchase' mechanic exists. Mitigation is via Safe Pockets, Free Loadouts, and the Vault (Expedition-only)."}]},
  {"id": "arc", "title": "Know Your ARC", "content": "Every machine has a tell and a weak point. The short version:", "bullets": ["Tick: small spider bots that latch on and drain health; melee them.", "Pop: rolling explosive; shoot at distance.", "Snitch: recon drone; scans, then calls two Wasps and a Hornet - kill or break line of sight fast.", "Wasp: hovering mid-range shooter; weak point is its four rear thrusters.", "Hornet: heavier Wasp with electrical shock; front thrusters protected.", "Rocketeer: flying rocket platform with splash damage; fight from cover.", "Bombardier: heavy flying artillery; stay inside/under cover.", "Bastion: heavy walker with sustained gunfire; open-ground killer.", "Sentinel: precise sniper-like shots; break line of sight.", "Leaper/Shredder: fast melee threats (Shredder added with Stella Montis).", "Matriarch and Queen: boss-class ARC tied to map conditions (Queen only during Harvester condition)."]},
  {"id": "prox-chat", "title": "Proximity Chat and Etiquette", "content": "95% of players use prox chat. Say 'friendly' / use the Don't Shoot voice line; silence usually means hostile. Solo players tend to be friendlier than duos/trios.", "bullets": ["Only ~30% of players focus on PvP; matchmaking sorts by aggression.", "Don't camp extraction points.", "Announce yourself before approaching.", "Don't loot a downed player you agreed to spare.", "Gunfire attracts both ARC and Raiders - sneak when you can."]},
  {"id": "tips", "title": "Top 20 Tips", "content": "Hard-won advice from the community, roughly in the order you will need it.", "bullets": ["Use Free Loadouts until you know the maps - they have no cooldown.", "Put Marathon Runner and Youthful Lungs first; stamina is life.", "Take Looter's Instincts + In-Round Crafting early.", "Build the Gunsmith and Gear Bench at Level 1 immediately - they are cheap.", "Upgrade Scrappy whenever you find fruit; passive materials snowball.", "Always put your most valuable item in the Safe Pocket.", "Sell trinkets and blueprints in Speranza; blueprints sell for 5,000 coins.", "Do Shani's and Celeste's early quests for big XP.", "Learn one map at a time; memorise 2+ extraction points.", "Extract early with a good haul instead of pushing your luck (greed is the #1 killer).", "Melee Ticks and Pops, don't waste ammo.", "Break line of sight from Snitches before they scan you.", "Shoot Wasps in the rear thrusters.", "Use prox chat - talking prevents most fights.", "Run one ammo type early (Kettle + Stitcher, both Light ammo).", "Don't bring gear you can't afford to lose.", "Craft ammo and bandages before deploying; buying is expensive.", "Refiner Level 2 unblocks every other Level-2 upgrade.", "Keep a coin reserve for stash upgrades and a 2,000/point respec.", "Reach level 20 before worrying about Expeditions; departure resets almost everything."]},
  {"id": "mistakes", "title": "Common Mistakes", "content": "", "bullets": ["Over-investing in expensive loadouts early", "Fighting every ARC (gunfire draws players)", "Ignoring stamina skills", "Not using Safe Pockets", "Spreading skill points across all three branches (you can only afford ~2 capstone branches)", "Spending coins on Ermal's stash expansion before an Expedition (it wipes)", "Selling workshop-upgrade materials (Wasp Drivers, Hornet Drivers, ARC Alloy)"]},
  {"id": "early-loadouts", "title": "Early Loadouts", "content": "Cheap, effective kits for your first twenty levels.", "subsections": [{"title": "Light ammo starter", "content": "One ammo type, cheap, good range coverage.", "bullets": ["Weapons: Kettle, Stitcher", "Shield: Light Shield"]}, {"title": "Ferro standard", "content": "Reliable, easy to craft, often a quest reward.", "bullets": ["Weapons: Ferro (assault rifle)", "Shield: Light/Medium"]}, {"title": "Medium/heavy backup", "content": "Bring at least one medium/heavy-ammo gun for Bastions/Sentinels.", "bullets": ["Weapons: Ferro or Rattler + shotgun (Anvil/Bettina)", "Shield: Medium"]}]},
  {"id": "money", "title": "Making Coins", "content": "", "bullets": ["Buried City Library loop: 4-6 min, 15-30k coins, low risk", "Buried City R&A mid-floor: 8-12 min, 30-60k per sweep", "Stella Montis Space Travel trinket farm: 50-80k per run", "Buried City Plaza Rosa Night Raid: 100k+ per run, high risk", "Blueprint farming (5,000 coins each)", "Security lockers with the Security Breach capstone", "Keep raids to 8-10 minutes and a 70%+ survival rate"]},
  {"id": "xp", "title": "Levelling Fast", "content": "~10,000 XP per level early; requirement grows gradually to a fixed maximum at higher levels. Full table not captured. ~15,000-25,000 XP per hour for an efficient PvE looter.", "bullets": ["Chain safe extractions while looting everything", "Solo ARC destruction (100% damage XP)", "Trader quests, especially Shani's early ones", "Maps with 2+ extractions and clustered loot", "Stack contracts/challenges each raid"]},
  {"id": "skill-points", "title": "Skill Points and Respec", "content": "2026 meta: Mobility-first, Survival second, Conditioning as late-game support. Solo/looter builds lean Survival (Silent Scavenger, Security Breach); PvP builds take Used to the Weight + Fight or Flight early.", "bullets": ["Total points to fill tree: 157", "Points from leveling: 76", "Points from expeditions: Up to 5 bonus points per completed early-Expedition challenge, permanent cap of 15 Expedition points (catch-up system added before the 2nd Expedition). From the 4th Expedition onward Embark replaced skill points as the main departure reward with Mystery Rewards (150 Raider Tokens per departure objective + one blueprint per objective); the 5th Expedition damage challenge still offers up to 5 points for players below the 15 cap.", "How points are earned: 1 Skill Point per Raider level-up (XP from looting containers, destroying ARC, quests, surviving/extracting, contracts).", "Tier gates: Each branch is gated by points spent inside that branch: 15 points opens the middle tier, 36 points opens both of the branch's capstones (plus specific prerequisite nodes). Most minor perks are 5-rank; major nodes are single-rank unlocks. Three capstones is the practical ceiling and costs all 76 points; every three-capstone build spends nothing in its third branch.", "Respec: Added in the Cold Snap update (Dec 2025). Raider menu > Skills > Reset. Costs 2,000 coins per assigned skill point; resets the ENTIRE tree at once (no single-node refunds); coins only (no premium currency). A full 75-point respec is ~150,000 coins. Expedition departure also fully resets skills for free.", "Recommended first 15: Nimble Climber -> Marathon Runner 5/5 -> Youthful Lungs 5/5 (15 Mobility) -> Carry the Momentum; then Survival: Looter's Instincts 5/5, Broad Shoulders, In-Round Crafting, Looter's Luck; then Conditioning: Used to the Weight 5/5 and Fight or Flight."]}
];

